CREATE DATABASE IF NOT EXISTS restaurant_reservation CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE restaurant_reservation;
CREATE TABLE IF NOT EXISTS dining_tables (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,label VARCHAR(40) NOT NULL UNIQUE,seats TINYINT UNSIGNED NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,CONSTRAINT chk_table_seats CHECK(seats BETWEEN 1 AND 20));
CREATE TABLE IF NOT EXISTS reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_name VARCHAR(100) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(30) NOT NULL,table_id INT UNSIGNED NOT NULL,party_size TINYINT UNSIGNED NOT NULL,reserved_at DATETIME NOT NULL,duration_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 90,status ENUM('confirmed','cancelled') NOT NULL DEFAULT 'confirmed',notes VARCHAR(500),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_reservation_table FOREIGN KEY(table_id) REFERENCES dining_tables(id),CONSTRAINT chk_party_size CHECK(party_size BETWEEN 1 AND 20),CONSTRAINT chk_duration CHECK(duration_minutes BETWEEN 30 AND 240),INDEX idx_reservations_slot(table_id,reserved_at,status));
CREATE TABLE IF NOT EXISTS events (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL,description TEXT,starts_at DATETIME NOT NULL,venue VARCHAR(120) NOT NULL,ticket_capacity INT UNSIGNED NOT NULL,ticket_price_centavos INT UNSIGNED NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS event_registrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id INT UNSIGNED NOT NULL,guest_name VARCHAR(100) NOT NULL,guest_email VARCHAR(254) NOT NULL,quantity TINYINT UNSIGNED NOT NULL,status ENUM('reserved','cancelled') NOT NULL DEFAULT 'reserved',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_registration_event FOREIGN KEY(event_id) REFERENCES events(id),CONSTRAINT chk_ticket_quantity CHECK(quantity BETWEEN 1 AND 10));
INSERT INTO dining_tables(id,label,seats) VALUES (1,'Garden 1',2),(2,'Garden 2',4),(3,'Main Hall 1',4),(4,'Family Table',8) ON DUPLICATE KEY UPDATE label=VALUES(label),seats=VALUES(seats);
INSERT INTO events(id,title,description,starts_at,venue,ticket_capacity,ticket_price_centavos) VALUES (1,'Season’s Wine Dinner','An intimate celebration of seasonal cuisine','2026-12-18 19:00:00','Main dining room',40,500000),(2,'Chef’s Tasting Night','A curated evening of signature dishes','2026-12-22 18:30:00','Garden dining area',30,250000) ON DUPLICATE KEY UPDATE title=VALUES(title);
